from pathlib import Path
import re

P=Path('firmware/web/index.html'); s=P.read_text()

def rep(old,new,label):
    global s
    c=s.count(old)
    if c!=1: raise AssertionError(f'{label}: count={c}')
    s=s.replace(old,new,1)

