# Safe telemetry details: static markup, text nodes for external strings.
old="$('sysDetails').innerHTML=`<strong>Uptime:</strong> ${sysUptime(d.uptimeMs)} • <strong>Firmware:</strong> v${d.version||'—'} • <strong>BLE:</strong> ${d.bleCount||0} connected<br><strong>Wi-Fi:</strong> ${d.ssid||'—'} • <strong>IP:</strong> ${d.ip||'—'} • <strong>Largest RAM block:</strong> ${sysBytes(d.heapLargest)}<br><strong>Last restart:</strong> ${d.resetReason||'—'} • <strong>Recovery watchdog:</strong> ${d.loopWatchdog?'Active':'Unavailable'} • <strong>Wi-Fi recoveries:</strong> ${d.networkRestarts||0}<br><strong>Reboot schedule:</strong> ${d.rebootSchedule||'12:00 AM • 6:00 AM • 12:00 PM • 6:00 PM'}`"
new="{const details=$('sysDetails');details.replaceChildren();const lines=[['Uptime',sysUptime(d.uptimeMs),'Firmware','v'+(d.version||'—'),'BLE',(d.bleCount||0)+' connected'],['Wi-Fi',d.ssid||'—','IP',d.ip||'—','Largest RAM block',sysBytes(d.heapLargest)],['Last restart',d.resetReason||'—','Recovery watchdog',d.loopWatchdog?'Active':'Unavailable','Wi-Fi recoveries',String(d.networkRestarts||0)],['Reboot schedule',d.rebootSchedule||'12:00 AM • 6:00 AM • 12:00 PM • 6:00 PM']];lines.forEach((line,li)=>{for(let i=0;i<line.length;i+=2){const strong=document.createElement('strong');strong.textContent=line[i]+':';details.append(strong,document.createTextNode(' '+String(line[i+1])+(i+2<line.length?' • ':''))}if(li+1<lines.length)details.appendChild(document.createElement('br'))})}"
rep(old,new,'safe system telemetry render')

# Firmware reconnect: reachability is not success; verify expected partition/version.
s=s.replace("let otaBeforePartition='';async function loadFirmwareInfo()","let otaBeforePartition='',otaExpectedPartition='',otaExpectedVersion='';async function loadFirmwareInfo()")
s=s.replace("otaBeforePartition=f.runningPartition||otaBeforePartition;","otaBeforePartition=f.runningPartition||otaBeforePartition;otaExpectedPartition=f.nextPartition||otaExpectedPartition;")
old="async function waitForFirmwareReturn(){let tries=0;$('fwStatus').textContent='NanoC6 is rebooting. Waiting for Wi-Fi and the web server to return…';const poll=async()=>{tries++;try{const {response:r,text}=await controllerRequest('/api/firmware?ts='+Date.now(),{cache:'no-store'},5000);if(r.ok){const f=JSON.parse(text);if(!otaBeforePartition||f.runningPartition!==otaBeforePartition||tries>=8){$('fwStatus').textContent='New firmware is running. Refreshing Anderson Home…';setTimeout(()=>location.reload(),700);return}}}catch(e){}if(tries<45){if(tries===6)$('fwStatus').textContent='Controller is restarting. Still waiting for Wi-Fi…';if(tries===15)$('fwStatus').textContent='Wi-Fi reconnect is taking longer than usual. Still checking…';setTimeout(poll,1000)}else{$('fwStatus').textContent='Firmware installation finished, but automatic reconnect timed out. Reopen Anderson Home.';$('uploadFirmware').disabled=false}};setTimeout(poll,2600)}"
new="async function waitForFirmwareReturn(){let tries=0;$('fwStatus').textContent='NanoC6 is rebooting. Waiting for Wi-Fi and the web server to return…';const poll=async()=>{tries++;try{const {response:r,text}=await controllerRequest('/api/firmware?ts='+Date.now(),{cache:'no-store'},5000);if(r.ok){const f=JSON.parse(text),partitionVerified=otaExpectedPartition&&f.runningPartition===otaExpectedPartition,versionVerified=otaExpectedVersion&&((f.version||f.appVersion)===otaExpectedVersion);if(partitionVerified||versionVerified){$('fwStatus').textContent=`Verified firmware ${f.version||f.appVersion||''} is running on ${f.runningPartition||'the target slot'}. Refreshing Anderson Home…`;setTimeout(()=>location.reload(),700);return}if(f.runningPartition){$('fwStatus').textContent=`Controller is reachable on ${f.runningPartition}, but the requested firmware has not been verified running yet. Still checking…`}}}catch(e){}if(tries<45){if(tries===6)$('fwStatus').textContent='Controller is restarting. Still waiting for the target firmware…';if(tries===15)$('fwStatus').textContent='Wi-Fi reconnect is taking longer than usual. Still verifying the running image…';setTimeout(poll,1000)}else{$('fwStatus').textContent='Controller reconnect check ended without verifying the requested firmware. The old image may still be running or may have rolled back.';$('uploadFirmware').disabled=false}};setTimeout(poll,2600)}"
rep(old,new,'verified firmware return')
# Remote update knows target version; manual relies on expected target partition captured by loadFirmwareInfo.
s=s.replace("if(d.ok&&d.installReady){out.textContent=","if(d.ok&&d.installReady){otaExpectedVersion=d.availableVersion||remoteUpdateVersion;out.textContent=",1)

# Remove dead firmware-locked color mutation stubs; rgbSave does not exist.
s=re.sub(r"\nasync function saveCurrentColor\(\).*?\nasync function removeSavedColor\(c\).*?\n",'\n',s,count=1)
s=s.replace("const saveFavorite=$('rgbSave');if(saveFavorite)saveFavorite.addEventListener('click',saveCurrentColor);",'')

P.write_text(s)

# v3 visual effect picker: four supported effects only and no 350ms hidden-control poll.
P=Path('firmware/web/v3_mockup.js'); v=P.read_text()
v=v.replace("const values=['Jump','Breath','Strobe','Gradient','Solid'];","const values=['Jump','Breath','Strobe','Solid'];")
v=v.replace("const labels={Jump:'Jump',Breath:'Breath',Strobe:'Strobe',Gradient:'Gradient',Solid:'Solid'};","const labels={Jump:'Jump',Breath:'Breath',Strobe:'Strobe',Solid:'Solid'};")
v=v.replace("const hints={Jump:'Snaps between colors',Breath:'Gently fades in and out',Strobe:'Flashes on and off',Gradient:'Flows through the palette',Solid:'Holds one color steady'};","const hints={Jump:'Snaps between colors',Breath:'Gently fades in and out',Strobe:'Flashes on and off',Solid:'Holds one color steady'};")
v=v.replace('grid-template-columns:repeat(5,minmax(0,1fr))','grid-template-columns:repeat(4,minmax(0,1fr))')
v=re.sub(r'\n\.v3EffectButton\[data-effect="Gradient"\].*?(?=\n\.v3EffectButton\[data-effect="Solid"\])','',v,flags=re.S)
v=re.sub(r'\n@keyframes v3FxGradient\{.*?\}','',v,flags=re.S)
v=v.replace("    setInterval(()=>qa('select[data-v3-effect-preview=\"1\"]').forEach(sync),350);\n",'')
P.write_text(v)

# Invariants.
s=Path('firmware/web/index.html').read_text(); v=Path('firmware/web/v3_mockup.js').read_text()
assert 'eventsSchedule1Toggle' not in s and 'eventsSchedule2Toggle' not in s
assert 'enableMonth' not in s and 'clearMonth' not in s
assert "effect:'Gradient'" not in s and '>Gradient<' not in s
assert "data-effect=\"Gradient\"" not in v and 'v3FxGradient' not in v
assert '/api/events/bulk' not in s
assert 'eventColorsOriginal' in s and 'eventColorsModern' in s
print('v3.1.0 web patch applied')
